create table if not exists public.crm_invoices (id uuid primary key default gen_random_uuid(), tenant_id uuid not null references public.tenants(id) on delete cascade, client_email text, invoice_number text, status text not null default 'draft', total numeric(12,2) not null default 0, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table if not exists public.crm_projects (id uuid primary key default gen_random_uuid(), tenant_id uuid not null references public.tenants(id) on delete cascade, client_email text, title text not null, status text not null default 'not_started', created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table if not exists public.crm_client_services (id uuid primary key default gen_random_uuid(), tenant_id uuid not null references public.tenants(id) on delete cascade, client_email text, plan text, status text not null default 'active', created_at timestamptz not null default now(), updated_at timestamptz not null default now());
alter table public.crm_invoices enable row level security; alter table public.crm_projects enable row level security; alter table public.crm_client_services enable row level security;
